// users.json is { uid: { profile: { name, stats: { dond_classic: {wins,...}, ... } } }, ... } or null.
const CATEGORIES = [
  { key: 'dond_classic', label: '⚡ صفقة سريع' },
  { key: 'dond_full', label: '🏟️ صفقة كامل' },
  { key: 'mazad_classic', label: '🔨 مزاد سريع' },
  { key: 'mazad_full', label: '🔨 مزاد كامل' }
];

const users = $input.first().json || {};
const digest = {};

for (const cat of CATEGORIES) {
  const rows = [];
  for (const uid of Object.keys(users)) {
    const profile = users[uid] && users[uid].profile;
    const stat = profile && profile.stats && profile.stats[cat.key];
    if (stat && stat.wins > 0) {
      rows.push({ name: profile.name || 'unknown', wins: stat.wins, losses: stat.losses || 0, totalMatches: stat.totalMatches || 0 });
    }
  }
  rows.sort((a, b) => b.wins - a.wins);
  digest[cat.key] = { label: cat.label, top: rows.slice(0, 5) };
}

return [{ json: { generatedAt: new Date().toISOString(), categories: digest } }];
